## This module adds modern .NET support for Winim. It lets Nim load .NET
## libraries, create objects, call methods, access properties, and use common
## .NET features such as collections, events, and asynchronous operations.
## Full features require .NET 8+; lower versions may not support some features.
##
## A typical program starts the .NET runtime, loads a library, creates an
## object, and closes the runtime when it is finished:
##
## .. code-block:: Nim
##    import winim/dotnet
##
##    block:
##      dotnetStart()
##      defer: dotnetClose()
##
##      let core = load("System.Private.CoreLib")
##      let builder = core.new("System.Text.StringBuilder")
##      builder.Append("Hello from Nim")
##      echo builder
##
## Instance methods and properties can be accessed with dot syntax. Static
## methods and properties are accessed through a type from the same library:
##
## .. code-block:: Nim
##    import winim/dotnet
##
##    block:
##      dotnetStart()
##      defer: dotnetClose()
##
##      let core = load("System.Private.CoreLib")
##      let int32Type = core.getType("System.Int32")
##      echo int32Type.Parse("12345")
##      echo int32Type.MaxValue
##
## The same interface can be used with .NET collections. Collections can be
## indexed, modified, and iterated:
##
## .. code-block:: Nim
##    import winim/dotnet
##
##    block:
##      dotnetStart()
##      defer: dotnetClose()
##
##      let collections = load("System.Collections.NonGeneric")
##      let items = collections.new("System.Collections.ArrayList")
##      for item in ["one", "two", "three"]:
##        items.Add(item)
##      echo items[0]
##      items[0] = "ONE"
##      for item in items:
##        echo item
##
## The examples above show the basic calling style. For a larger walkthrough,
## see `examples/dotnet/usage_demo.nim`. Windows Forms and event handling are
## shown in `examples/dotnet/simple_gui.nim`, while asynchronous .NET calls
## are shown in `examples/dotnet/async_download.nim`.
##
## .NET objects are cleaned up automatically. Use `release` when an object
## should be released before its surrounding scope ends, and call
## `dotnetClose` when the program is finished with .NET.

when not defined(windows):
  {.fatal: "winim/dotnet requires a Windows target".}

{.experimental.}

import lean
import inc/objbase
import std/[macros, os, strutils, base64, tempfiles, tables, asyncdispatch, locks]
export lean, objbase

type
  DotnetError* = object of CatchableError
    ## Raised when hosting or a managed bridge operation fails.
    code*: int32                 ## Hostfxr or Win32 error code.

  DotnetTaskCanceledError* = object of DotnetError
    ## Raised when an awaited managed `Task` or `ValueTask` was canceled.

  DotnetHost = ref object
    runtimeConfigPath: string
      ## Runtimeconfig path; generated files are removed after startup.
    runtimeConfigGenerated: bool
      ## Whether the runtimeconfig was generated automatically.
    frameworkName: string
      ## Shared framework requested at startup.
    frameworkVersion: string
      ## Selected shared framework version.
    hostfxrPath: string
      ## Loaded `hostfxr.dll` path.
    dotnetRoot: string
      ## .NET installation root.
    closed: bool
      ## Whether `close` has been called.
    hostfxrModule: HMODULE
    ownerThreadId: DWORD
    context: HostfxrHandle
    initialize: HostfxrInitializeForRuntimeConfigProc
    setErrorWriter: HostfxrSetErrorWriterProc
    getRuntimeDelegate: HostfxrGetRuntimeDelegateProc
    closeContext: HostfxrCloseProc
    loadAssemblyAndGetFunctionPointer: LoadAssemblyAndGetFunctionPointerProc
    getFunctionPointer: GetFunctionPointerProc
    loadAssemblyProc: LoadAssemblyProc
    loadAssemblyBytesProc: LoadAssemblyBytesProc
    frameworkPaths: seq[string]
    objectBridgeMethod: pointer
    delegateBridgeLoaded: bool
    managedHandles: Table[pointer, bool]
    startupRuntimeConfigPath: string
    startupHostfxrPath: string
    startupDotnetRoot: string
    startupFrameworkName: string
    startupFrameworkVersion: string

  DotnetObjectData = object
    handle: pointer
    host: DotnetHost
    owned: bool

  DotnetObject* = ref DotnetObjectData ## An opaque CoreCLR object or boxed-value handle.

  DotnetRuntimeInfo* = object
    ## Read-only information about the current thread's .NET host.
    runtimeConfigPath*: string
    runtimeConfigGenerated*: bool
    frameworkName*: string
    frameworkVersion*: string
    hostfxrPath*: string
    dotnetRoot*: string

  DotnetClass* = ref object
    ## A type proxy for constructors and static members.
    typeName*: string       ## Managed type name.
    assemblyName*: string   ## Optional assembly identity.
    host: DotnetHost

  DotnetAssembly* = ref object
    ## A loaded assembly used for type lookup and construction.
    name*: string   ## Assembly name without `.dll`.
    path*: string   ## Resolved absolute assembly path.
    host: DotnetHost

  DotnetMethod* = object
    ## A native address for one managed static method.
    ##
    ## Use `asProc` only with a Nim proc type whose calling convention and
    ## parameter layout exactly match the managed delegate type used during
    ## lookup. The address is valid while the associated host remains open.
    address*: pointer   ## Native entry-point address.
    host: DotnetHost

  DotnetValueKind* = enum
    Null,        ## A managed null reference.
    Bool,        ## A Boolean value.
    Int64,       ## A signed integer value.
    UInt64,      ## An unsigned integer value.
    Float64,     ## A floating-point value.
    String,      ## A UTF-8 Nim string converted to String.
    Object       ## An existing managed object or boxed value.

  DotnetValue* = object
    ## Primitive or object value passed to a managed constructor, property, or
    ## method. Create complex values through managed APIs.
    case kind*: DotnetValueKind
    of Null: discard
    of Bool: boolValue*: bool                ## Value stored for `Bool`.
    of Int64: int64Value*: int64             ## Value stored for `Int64`.
    of UInt64: uint64Value*: uint64          ## Value stored for `UInt64`.
    of Float64: float64Value*: float64       ## Value stored for `Float64`.
    of String: stringValue*: string          ## Value stored for `String`.
    of Object: objectValue*: DotnetObject    ## Handle stored for `Object`.

  DotnetEventToken* = object
    ## Opaque identity for one managed event registration. Use it on the thread
    ## that called `on`.
    host: DotnetHost
    eventId: uint64

  DotnetApplicationRunState = ref object
    host: DotnetHost
    application: DotnetClass
    pendingException: ref Exception

  DotnetEventRegistration = ref object
    host: DotnetHost
    target: DotnetObject
    eventName: string
    eventId: uint64
    handler: DotnetEventHandler

  DotnetDelegateRegistration = ref object
    host: DotnetHost
    callback: DotnetDelegateCallback
    parameterCount: int

  DotnetBridgeResponseDescriptor = object
    data: pointer
    length: int32
    status: int32

  HostfxrHandle = pointer

  HostfxrDelegateType = enum
    comActivation = 0,
    loadInMemoryAssembly,
    winrtActivation,
    comRegister,
    comUnregister,
    loadAssemblyAndGetFunctionPointer,
    getFunctionPointer,
    loadAssembly,
    loadAssemblyBytes

  DotnetBridgeOperation = enum
    create = 1,
    get,
    setValue,
    invoke,
    staticGet,
    staticSet,
    staticInvoke,
    boxEnum,
    releaseHandle,
    addEvent,
    removeEvent,
    clearEvents,
    convertToString,
    convertToInt64,
    convertToBool,
    pollEvent,
    disposeObject

  DotnetComponentEntryPoint* = proc(data: pointer, size: int32): int32 {.stdcall.}
    ## Default signature for `load` and `getMethod`.

  DotnetEventHandler* = proc(sender, args: DotnetObject) {.closure.}
    ## Callback invoked by `pollEvents` for an event registered with `on`.

  DotnetDelegateCallback* = proc(args: openArray[DotnetObject]): DotnetObject {.closure.}
    ## Callback invoked by a managed delegate created with `newDelegate`.
    ## Arguments are valid managed object wrappers for the duration of the call.
    ## Return a managed value compatible with the delegate return type, or nil
    ## for `void` and nullable/reference return types.

  DotnetDelegateEntryPoint = proc(context, arguments: pointer): pointer {.stdcall.}

  DotnetDelegateBodyBuilder* = proc(expression: DotnetClass, parameters: seq[DotnetObject]): DotnetObject {.closure.}
    ## Builds the expression body for a managed delegate. `parameters` are
    ## created from the delegate's `Invoke` signature.

  HostfxrInitializeParameters {.pure.} = object
    size: csize_t
    hostPath: LPCWSTR
    dotnetRoot: LPCWSTR

  HostfxrInitializeForRuntimeConfigProc = proc(
    runtimeConfigPath: LPCWSTR,
    parameters: ptr HostfxrInitializeParameters,
    hostContext: ptr HostfxrHandle
  ): int32 {.cdecl.}

  HostfxrErrorWriterProc = proc(message: LPCWSTR) {.cdecl.}

  HostfxrSetErrorWriterProc = proc(
    errorWriter: HostfxrErrorWriterProc
  ): HostfxrErrorWriterProc {.cdecl.}

  HostfxrGetRuntimeDelegateProc = proc(
    hostContext: HostfxrHandle,
    delegateType: HostfxrDelegateType,
    delegate: ptr pointer
  ): int32 {.cdecl.}

  HostfxrFrameworkResult = object
    size: csize_t
    name: LPCWSTR
    requestedVersion: LPCWSTR
    resolvedVersion: LPCWSTR
    resolvedPath: LPCWSTR

  ResolvedFramework = object
    name: string
    version: string
    path: string

  ResolveState = object
    paths: seq[string]
    frameworks: seq[ResolvedFramework]

  HostfxrResolveFrameworksResult = object
    size: csize_t
    resolvedCount: csize_t
    resolvedFrameworks: ptr HostfxrFrameworkResult
    unresolvedCount: csize_t
    unresolvedFrameworks: ptr HostfxrFrameworkResult

  HostfxrResolveFrameworksResultProc = proc(
    result: ptr HostfxrResolveFrameworksResult,
    context: pointer
  ) {.cdecl.}

  HostfxrResolveFrameworksForRuntimeConfigProc = proc(
    runtimeConfigPath: LPCWSTR,
    parameters: ptr HostfxrInitializeParameters,
    callback: HostfxrResolveFrameworksResultProc,
    context: pointer
  ): int32 {.cdecl.}

  HostfxrCloseProc = proc(hostContext: HostfxrHandle): int32 {.cdecl.}

  LoadAssemblyAndGetFunctionPointerProc = proc(
    assemblyPath: LPCWSTR,
    typeName: LPCWSTR,
    methodName: LPCWSTR,
    delegateTypeName: LPCWSTR,
    reserved: pointer,
    delegate: ptr pointer
  ): int32 {.stdcall.}

  GetFunctionPointerProc = proc(
    typeName: LPCWSTR,
    methodName: LPCWSTR,
    delegateTypeName: LPCWSTR,
    loadContext: pointer,
    reserved: pointer,
    delegate: ptr pointer
  ): int32 {.stdcall.}

  LoadAssemblyProc = proc(
    assemblyPath: LPCWSTR,
    loadContext: pointer,
    reserved: pointer
  ): int32 {.stdcall.}

  LoadAssemblyBytesProc = proc(
    assemblyBytes: pointer,
    assemblyBytesLength: csize_t,
    symbolsBytes: pointer,
    symbolsBytesLength: csize_t,
    loadContext: pointer,
    reserved: pointer
  ): int32 {.stdcall.}

proc releaseManagedHandle(host: DotnetHost, handle: pointer, owned: bool) {.raises: [Exception].}
proc releaseDotnetHandle(self: var DotnetObjectData) {.raises: [Exception].}
proc clearDotnetEvents(host: DotnetHost)
proc clearDotnetDelegates(host: DotnetHost)
proc releaseDotnetObjects(host: DotnetHost)
when not defined(gcDestructors):
  proc finalizeDotnetObject(self: DotnetObject)

const dotnetArcLike = defined(gcArc) or defined(gcAtomicArc) or defined(gcOrc)
when defined(nimAllowNonVarDestructor) and dotnetArcLike:
  proc `=destroy`(self: DotnetObjectData) {.raises: [Exception].} =
    releaseManagedHandle(self.host, self.handle, self.owned)
else:
  proc `=destroy`(self: var DotnetObjectData) {.raises: [Exception].} =
    releaseDotnetHandle(self)

const
  UnmanagedCallersOnly* = "*" ## Pass as `delegateType` to `load` or `getMethod` to select `UnmanagedCallersOnly`
  hostfxrSuccess = 0'i32
  hostfxrAlreadyInitialized = 1'i32
  hostfxrDifferentRuntimeProperties = 2'i32
  dotnetMissingMethodHResult = cast[int32](0x80131513'u32)
  dotnetMissingMemberHResult = cast[int32](0x80131512'u32)
  # A non-generic managed delegate type is required by
  # Marshal.GetDelegateForFunctionPointer.
  DotnetDelegateBridgeAssemblyName = "WinimDotnetDelegateBridge"
  DotnetDelegateBridgeAssemblyBase64 = """"""
  DotnetObjectBridgeAssemblyName = "WinimDotnetBridge"
  DotnetObjectBridgeAssemblyBase64 = """"""

var
  CurrentHost {.threadvar.}: DotnetHost
  HostfxrErrorOutput {.threadvar.}: string
  DotnetDesktopApartmentInitialized {.threadvar.}: bool
  HostfxrInitializationAttempted: bool
  HostfxrRuntimeInitialized: bool
  HostfxrBootstrapModule: HMODULE
  HostfxrStateLock: Lock
  DotnetDelegateLock: Lock
  DotnetApplicationRunStates {.threadvar.}: Table[UINT_PTR, DotnetApplicationRunState]
  DotnetEventRegistrations {.threadvar.}: Table[uint64, DotnetEventRegistration]
  DotnetDelegateRegistrations: Table[pointer, DotnetDelegateRegistration]
  NextDotnetEventId: int64 = int64(uint32.high)

initLock(HostfxrStateLock)
initLock(DotnetDelegateLock)

template addrptr[T](x: openArray[T]): pointer =
  if x.len == 0: nil else: x[0].addr

template wstrptr(x: string): LPCWSTR =
  if x.len == 0: nil else: &(+$x)

proc collectHostfxrError(message: LPCWSTR) {.cdecl.} =
  if not message.isNil:
    if HostfxrErrorOutput.len != 0: HostfxrErrorOutput.add '\n'
    HostfxrErrorOutput.add($message)

proc dotnetError(message: string, code: int32 = 0) {.noreturn.} =
  var error = newException(DotnetError, message)
  error.code = code
  raise error

proc collectResolvedFrameworks(info: ptr HostfxrResolveFrameworksResult, context: pointer) {.cdecl.} =
  if info.isNil or info.resolvedFrameworks.isNil:
    return

  let
    state = cast[ptr ResolveState](context)
    frameworks = cast[ptr UncheckedArray[HostfxrFrameworkResult]](info.resolvedFrameworks)

  for index in 0 ..< int(info.resolvedCount):
    let
      framework = frameworks[index]
      path =
        if framework.resolvedPath.isNil: ""
        else: $framework.resolvedPath

    state[].frameworks.add ResolvedFramework(
      name:
        if framework.name.isNil: ""
        else: $framework.name,
      version:
        if framework.resolvedVersion.isNil: ""
        else: $framework.resolvedVersion,
      path: path)

    if path.len != 0:
      state[].paths.add path

proc ensureDotnetDesktopApartment() =
  if not DotnetDesktopApartmentInitialized:
    let hr = CoInitializeEx(nil, COINIT_APARTMENTTHREADED)
    case hr
    of S_OK, S_FALSE:
      DotnetDesktopApartmentInitialized = true
    of RPC_E_CHANGED_MODE:
      dotnetError("Microsoft.WindowsDesktop.App requires an STA thread", hr)
    else:
      dotnetError("unable to initialize COM for Microsoft.WindowsDesktop.App", hr)

proc checkHostfxr(code: int32, message: string) =
  if code != hostfxrSuccess:
    dotnetError(message, code)

proc checkInitialization(code: int32, message: string) =
  if code != hostfxrSuccess and
      code != hostfxrAlreadyInitialized and
      code != hostfxrDifferentRuntimeProperties:
    dotnetError(message, code)

proc checkedInt32Length(value: int): int32 =
  if value < 0 or uint64(value) > uint64(int32.high):
    dotnetError("invalid managed length", E_INVALIDARG)
  return int32(value)

proc getHostfxrExport[T](library: HMODULE, name: string): T =
  let address = GetProcAddress(library, name)
  if address.isNil:
    dotnetError("unable to find hostfxr export: " & name)
  return cast[T](address)

proc versionPart(version: string, index: int): int =
  let parts = version.split('.')
  if index >= parts.len: return 0

  for c in parts[index]:
    if c < '0' or c > '9': break
    result = result * 10 + ord(c) - ord('0')

proc compareVersion(left, right: string): int =
  for i in 0 .. 3:
    let l = versionPart(left, i)
    let r = versionPart(right, i)
    if l < r: return -1
    if l > r: return 1

proc satisfies(selected, requested: string): bool {.inline.} =
  requested.len == 0 or
    (versionPart(selected, 0) == versionPart(requested, 0) and
     versionPart(selected, 1) == versionPart(requested, 1) and
     compareVersion(selected, requested) >= 0)

proc dotnetRootFromRegistry(): string =
  const
    architecture =
      when hostCPU == "amd64": "x64"
      elif hostCPU == "arm64": "arm64"
      else: "x86"
    subKey = r"SOFTWARE\dotnet\Setup\InstalledVersions\" & architecture

  var key: HKEY
  if RegOpenKeyEx(HKEY_LOCAL_MACHINE, subKey, 0,
      REGSAM(KEY_READ or KEY_WOW64_32KEY), &key) != ERROR_SUCCESS: return
  defer: RegCloseKey(key)

  var valueSize: DWORD
  if RegGetValue(key, nil, "InstallLocation", RRF_RT_REG_SZ, nil, nil,
      &valueSize) != ERROR_SUCCESS or valueSize == 0: return

  var value = newWString(valueSize div sizeof(WCHAR))
  if RegGetValue(key, nil, "InstallLocation", RRF_RT_REG_SZ, nil, &value,
      &valueSize) != ERROR_SUCCESS: return

  return $value

proc findHostfxrInRoot(root: string): string =
  if root.len == 0: return
  let fxrRoot = absolutePath(root) / "host" / "fxr"
  if not dirExists(fxrRoot): return ""

  var bestVersion = ""
  for kind, path in walkDir(fxrRoot):
    if kind != pcDir: continue

    let candidate = path / "hostfxr.dll"
    if not fileExists(candidate): continue

    let version = extractFilename(path)
    if result.len == 0 or compareVersion(version, bestVersion) > 0:
      result = candidate
      bestVersion = version

proc findHostfxr(dotnetRoot: string): string =
  template tryRoot(rootExpr: string) =
    let candidateRoot = rootExpr
    if candidateRoot.len != 0:
      let path = findHostfxrInRoot(candidateRoot)
      if path.len != 0: return path

  tryRoot(dotnetRoot)
  when hostCPU == "amd64":
    tryRoot(getEnv("DOTNET_ROOT_X64"))
  elif hostCPU == "arm64":
    tryRoot(getEnv("DOTNET_ROOT_ARM64"))
  else:
    tryRoot(getEnv("DOTNET_ROOT_X86"))
    tryRoot(getEnv("DOTNET_ROOT(x86)"))

  tryRoot(getEnv("DOTNET_ROOT"))
  tryRoot(dotnetRootFromRegistry())

  let programW6432 = getEnv("ProgramW6432")
  if programW6432.len != 0: tryRoot(programW6432 / "dotnet")

  let programFiles = getEnv("ProgramFiles")
  if programFiles.len != 0: tryRoot(programFiles / "dotnet")

  let programFilesX86 = getEnv("ProgramFiles(x86)")
  if programFilesX86.len != 0: tryRoot(programFilesX86 / "dotnet")

  let dotnetExe = findExe("dotnet.exe")
  if dotnetExe.len != 0: tryRoot(splitFile(dotnetExe).dir)

proc findLatestVersion(dotnetRoot, name: string, requested = ""): string =
  let frameworkRoot = dotnetRoot / "shared" / name
  if not dirExists(frameworkRoot): return

  for kind, path in walkDir(frameworkRoot):
    if kind != pcDir: continue

    let version = extractFilename(path)
    if not satisfies(version, requested): continue

    if result.len == 0 or compareVersion(version, result) > 0:
      result = version

proc makeRuntimeConfig(frameworkName, frameworkVersion: string): string =
  if frameworkName.len == 0 or frameworkVersion.len == 0:
    dotnetError("framework name and version are required for an inline runtimeconfig")
  if frameworkName.contains('"') or frameworkVersion.contains('"'):
    dotnetError("framework name and version cannot contain quotes")
  result = """{"runtimeOptions":{"framework":{"name":"$1","version":"$2"}}}""" %
    [frameworkName, frameworkVersion]

proc normalizeHostfxrPath(path: string): string =
  if fileExists(path): return absolutePath(path)

  if dirExists(path):
    let candidate = path / "hostfxr.dll"
    if fileExists(candidate): return absolutePath(candidate)

proc absolutePathOrEmpty(path: string): string =
  if path.len == 0: "" else: absolutePath(path)

proc dotnetRootFromHostfxr(path: string): string =
  # A normal hostfxr path is <dotnet root>/host/fxr/<version>/hostfxr.dll.
  result = splitFile(path).dir.parentDir.parentDir.parentDir

proc getDelegate[T](host: DotnetHost, delegateType: HostfxrDelegateType, required = false): T =
  let code = host.getRuntimeDelegate(host.context, delegateType, cast[ptr pointer](&result))
  if code != hostfxrSuccess:
    if required: dotnetError("unable to get hostfxr runtime delegate", code)
    return nil

  if result.isNil and required:
    dotnetError("hostfxr returned a nil runtime delegate", E_UNEXPECTED)

proc clearHostFunctionPointers(host: DotnetHost) =
  host.initialize = nil
  host.setErrorWriter = nil
  host.getRuntimeDelegate = nil
  host.closeContext = nil
  host.loadAssemblyAndGetFunctionPointer = nil
  host.getFunctionPointer = nil
  host.loadAssemblyProc = nil
  host.loadAssemblyBytesProc = nil
  host.objectBridgeMethod = nil

proc sameStartupRequest(host: DotnetHost, runtimeConfigPath, hostfxrPath,
    dotnetRoot, frameworkName, frameworkVersion: string): bool =
  let
    configPath = absolutePathOrEmpty(runtimeConfigPath)
    rootPath = absolutePathOrEmpty(dotnetRoot)
    requestedHostfxr = absolutePathOrEmpty(hostfxrPath)

  result =
    configPath == host.startupRuntimeConfigPath and
    requestedHostfxr == host.startupHostfxrPath and
    rootPath == host.startupDotnetRoot and
    frameworkName == host.startupFrameworkName and
    frameworkVersion == host.startupFrameworkVersion

proc createDotnetHost(runtimeConfigPath = "", hostfxrPath = "", dotnetRoot = "",
    frameworkName = "Microsoft.NETCore.App", frameworkVersion = ""): DotnetHost =
  # Creates a .NET host through hostfxr. The caller owns assignment to the
  # current thread's host slot.
  if frameworkName.toLowerAscii == "microsoft.windowsdesktop.app":
    ensureDotnetDesktopApartment()

  var configPath = runtimeConfigPath
  if configPath.len == 0:
    configPath = changeFileExt(getAppFilename(), "runtimeconfig.json")
    if not fileExists(configPath): configPath = ""
  elif not fileExists(configPath):
    dotnetError("modern .NET runtimeconfig.json was not found: " & configPath)

  configPath = absolutePathOrEmpty(configPath)

  var libraryPath: string
  if hostfxrPath.len != 0:
    libraryPath = normalizeHostfxrPath(hostfxrPath)
    if libraryPath.len == 0:
      dotnetError("hostfxr.dll was not found: " & hostfxrPath, E_INVALIDARG)
  else:
    libraryPath = findHostfxr(dotnetRoot)

  if libraryPath.len == 0:
    dotnetError("unable to locate hostfxr.dll; pass hostfxrPath or dotnetRoot")

  let library = LoadLibraryEx(libraryPath, 0, 0)
  if library == 0:
    dotnetError("unable to load hostfxr.dll: " & libraryPath)

  # Reloading hostfxr after releasing its last reference loses the process-wide
  # initialization state while CoreCLR remains loaded (0x80008081 on the next
  # context). Retain one bootstrap reference; `library` is still per-host.
  var bootstrapCreated = false
  if HostfxrBootstrapModule == 0:
    HostfxrBootstrapModule = LoadLibraryEx(libraryPath, 0, 0)
    if HostfxrBootstrapModule == 0:
      FreeLibrary(library)
      dotnetError("unable to retain hostfxr bootstrap module: " & libraryPath)
    bootstrapCreated = true

  result = DotnetHost()
  result.startupRuntimeConfigPath = absolutePathOrEmpty(runtimeConfigPath)
  result.startupHostfxrPath = absolutePathOrEmpty(hostfxrPath)
  result.startupDotnetRoot = absolutePathOrEmpty(dotnetRoot)
  result.startupFrameworkName = frameworkName
  result.startupFrameworkVersion = frameworkVersion
  result.runtimeConfigPath = configPath
  result.frameworkName = frameworkName
  result.hostfxrPath = libraryPath
  result.dotnetRoot =
    if dotnetRoot.len != 0: absolutePath(dotnetRoot)
    else: dotnetRootFromHostfxr(libraryPath)

  result.hostfxrModule = library
  result.ownerThreadId = GetCurrentThreadId()
  var startupCompleted = false
  defer:
    if not startupCompleted:
      if not result.context.isNil and not result.closeContext.isNil:
        discard result.closeContext(result.context)
        result.context = nil

      result.clearHostFunctionPointers()
      if result.hostfxrModule != 0:
        FreeLibrary(result.hostfxrModule)
        result.hostfxrModule = 0

      if bootstrapCreated and not HostfxrRuntimeInitialized and HostfxrBootstrapModule != 0:
        FreeLibrary(HostfxrBootstrapModule)
        HostfxrBootstrapModule = 0
        HostfxrInitializationAttempted = false
      result.closed = true

  result.initialize = getHostfxrExport[HostfxrInitializeForRuntimeConfigProc](
    library, "hostfxr_initialize_for_runtime_config")
  result.setErrorWriter = getHostfxrExport[HostfxrSetErrorWriterProc](
    library, "hostfxr_set_error_writer")
  result.getRuntimeDelegate = getHostfxrExport[HostfxrGetRuntimeDelegateProc](
    library, "hostfxr_get_runtime_delegate")
  result.closeContext = getHostfxrExport[HostfxrCloseProc](
    library, "hostfxr_close")

  var tempFile: string
  defer:
    try:
      if tempFile != "": removeFile(tempFile)
    except OSError: discard

  if configPath.len == 0:
    if frameworkName.contains('"') or frameworkVersion.contains('"'):
      dotnetError("framework name and version cannot contain quotes")

    result.frameworkVersion = findLatestVersion(result.dotnetRoot, frameworkName, frameworkVersion)
    if result.frameworkVersion.len == 0:
      let versionSuffix =
        if frameworkVersion.len == 0: ""
        else: " " & frameworkVersion
      dotnetError("installed .NET framework was not found: " & frameworkName & versionSuffix)

    tempFile = genTempPath("winim-dotnet-", ".runtimeconfig.json")
    writeFile(tempFile, makeRuntimeConfig(frameworkName, result.frameworkVersion))
    configPath = absolutePath(tempFile)
    result.runtimeConfigPath = configPath
    result.runtimeConfigGenerated = true

  var
    rootWide: wstring
    parameters: HostfxrInitializeParameters
    parametersPtr: ptr HostfxrInitializeParameters

  if result.dotnetRoot.len != 0 and not HostfxrInitializationAttempted:
    rootWide = +$result.dotnetRoot
    parameters.size = csize_t(sizeof(parameters))
    parameters.dotnetRoot = &rootWide
    parametersPtr = &parameters

  let resolveFrameworks = getHostfxrExport[HostfxrResolveFrameworksForRuntimeConfigProc](
      library, "hostfxr_resolve_frameworks_for_runtime_config")
  var resolved: ResolveState
  let resolveCode = resolveFrameworks(+$configPath, parametersPtr, collectResolvedFrameworks, addr resolved)
  checkHostfxr(resolveCode, "unable to resolve modern .NET frameworks")

  result.frameworkPaths = resolved.paths
  if resolved.frameworks.len != 0:
    let primary = resolved.frameworks[0]
    result.frameworkName = primary.name
    result.frameworkVersion = primary.version

  HostfxrErrorOutput.setLen(0)
  let previousErrorWriter = result.setErrorWriter(collectHostfxrError)
  var initCode: int32
  try:
    HostfxrInitializationAttempted = true
    initCode = result.initialize(configPath, parametersPtr, &result.context)
  finally:
    discard result.setErrorWriter(previousErrorWriter)

  let initializationDetails = HostfxrErrorOutput
  HostfxrErrorOutput.setLen(0)
  let initializationMessage =
    if initializationDetails.len == 0: "unable to initialize modern .NET"
    else: "unable to initialize modern .NET" & ":\n" & initializationDetails

  try:
    checkInitialization(initCode, initializationMessage)
    if result.context.isNil: dotnetError("hostfxr returned a nil context", E_UNEXPECTED)

    HostfxrRuntimeInitialized = true
    HostfxrErrorOutput.setLen(0)
    let previousDelegateErrorWriter = result.setErrorWriter(collectHostfxrError)
    try:
      result.loadAssemblyAndGetFunctionPointer =
        getDelegate[LoadAssemblyAndGetFunctionPointerProc](result, loadAssemblyAndGetFunctionPointer, required = true)
      result.getFunctionPointer =
        getDelegate[GetFunctionPointerProc](result, getFunctionPointer)
      result.loadAssemblyProc =
        getDelegate[LoadAssemblyProc](result, loadAssembly)
      result.loadAssemblyBytesProc =
        getDelegate[LoadAssemblyBytesProc](result, loadAssemblyBytes)
    finally:
      discard result.setErrorWriter(previousDelegateErrorWriter)
      HostfxrErrorOutput.setLen(0)

  except CatchableError:
    if not result.context.isNil:
      discard result.closeContext(result.context)
      result.context = nil
    raise

  startupCompleted = true

proc dotnetStart*(runtimeConfigPath = "", hostfxrPath = "", dotnetRoot = "",
    frameworkName = "Microsoft.NETCore.App", frameworkVersion = "") =
  ## Starts or reuses the current thread's implicit .NET host.
  acquire(HostfxrStateLock)
  defer: release(HostfxrStateLock)

  if not CurrentHost.isNil and not CurrentHost.closed:
    if sameStartupRequest(CurrentHost, runtimeConfigPath, hostfxrPath, dotnetRoot, frameworkName, frameworkVersion):
      return

    dotnetError("a different modern .NET host is already active on this thread; call dotnetClose first", E_INVALIDARG)

  CurrentHost = createDotnetHost(runtimeConfigPath, hostfxrPath, dotnetRoot, frameworkName, frameworkVersion)

proc close(host: DotnetHost) =
  # Closes the host and releases its managed resources. Calling `close` again
  # after the host is closed has no effect.
  if host.isNil or host.closed: return
  if host.ownerThreadId != GetCurrentThreadId():
    dotnetError("modern .NET host must be closed on its owning thread", RPC_E_WRONG_THREAD)

  var firstError: ref Exception
  template attempt(action: untyped) =
    try:
      action
    except Exception:
      if firstError.isNil: firstError = getCurrentException()

  if not host.objectBridgeMethod.isNil and not host.context.isNil:
    attempt(clearDotnetEvents(host))
    attempt(releaseDotnetObjects(host))
  attempt(clearDotnetDelegates(host))

  host.closed = true
  if not host.context.isNil:
    let context = host.context
    host.context = nil
    attempt(checkHostfxr(host.closeContext(context), "unable to close modern .NET host"))

  host.clearHostFunctionPointers()
  if host.hostfxrModule != 0:
    let library = host.hostfxrModule
    host.hostfxrModule = 0
    if FreeLibrary(library) == 0:
      attempt(dotnetError("unable to unload hostfxr module", int32(GetLastError())))

  if CurrentHost == host: CurrentHost = nil
  if not firstError.isNil: raise firstError

proc dotnetClose*() =
  ## Closes the current thread's implicit .NET host.
  acquire(HostfxrStateLock)
  defer: release(HostfxrStateLock)
  close(CurrentHost)

proc requireOpen(host: DotnetHost) =
  if host.isNil:
    dotnetError("modern .NET host is nil", E_POINTER)
  if host.ownerThreadId != GetCurrentThreadId():
    dotnetError("modern .NET host must be used on its owning thread", RPC_E_WRONG_THREAD)
  if host.closed or host.context.isNil:
    dotnetError("modern .NET host is closed", E_HANDLE)

proc requireCurrentHost(): DotnetHost =
  if CurrentHost.isNil or CurrentHost.closed:
    dotnetError("modern .NET host has not been started; call dotnetStart first", E_UNEXPECTED)
  result = CurrentHost

proc dotnetRuntimeInfo*(): DotnetRuntimeInfo =
  ## Returns read-only information about the current thread's .NET host.
  let host = requireCurrentHost()
  result.runtimeConfigPath = host.runtimeConfigPath
  result.runtimeConfigGenerated = host.runtimeConfigGenerated
  result.frameworkName = host.frameworkName
  result.frameworkVersion = host.frameworkVersion
  result.hostfxrPath = host.hostfxrPath
  result.dotnetRoot = host.dotnetRoot

proc load(host: DotnetHost, assemblyPath, typeName, methodName: string, delegateType = ""): DotnetMethod {.discardable.} =
  # Loads a public static method from an assembly. Use an assembly-qualified
  # `typeName` for custom assemblies; use `delegateType` and `asProc[T]` for
  # non-default signatures. Pass `UnmanagedCallersOnly` or `"*"` for a method
  # marked `UnmanagedCallersOnly`.
  requireOpen(host)
  if host.loadAssemblyAndGetFunctionPointer.isNil:
    dotnetError("hostfxr load-assembly delegate is unavailable", E_NOTIMPL)

  result.host = host
  let delegateType =
    if delegateType == UnmanagedCallersOnly: cast[LPCWSTR](high(uint))
    else: wstrptr(delegateType)
  let code = host.loadAssemblyAndGetFunctionPointer(absolutePath(assemblyPath),
    typeName, methodName, delegateType, nil, &result.address)
  checkHostfxr(code, "unable to load method")
  if result.address.isNil:
    dotnetError("hostfxr returned a nil method pointer", E_UNEXPECTED)

proc getMethod(host: DotnetHost, typeName, methodName: string, delegateType = ""): DotnetMethod {.discardable.} =
  # Gets a public static method from an already loaded assembly. `typeName`
  # and `delegateType` follow the rules of `load`; pass `UnmanagedCallersOnly`
  # or `"*"` for a method marked `UnmanagedCallersOnly`.
  requireOpen(host)
  if host.getFunctionPointer.isNil:
    dotnetError("hostfxr get-function-pointer delegate is unavailable", E_NOTIMPL)

  result.host = host
  let delegateType =
    if delegateType == UnmanagedCallersOnly: cast[LPCWSTR](high(uint))
    else: wstrptr(delegateType)
  let code = host.getFunctionPointer(typeName, methodName, delegateType, nil, nil, &result.address)
  checkHostfxr(code, "unable to get method")
  if result.address.isNil:
    dotnetError("hostfxr returned a nil method pointer", E_UNEXPECTED)

proc loadAssembly(host: DotnetHost, assemblyPath: string) =
  # Loads a managed assembly by path; failures raise `DotnetError`.
  requireOpen(host)
  if host.loadAssemblyProc.isNil:
    dotnetError("hostfxr load-assembly delegate is unavailable", E_NOTIMPL)

  let code = host.loadAssemblyProc(absolutePath(assemblyPath), nil, nil)
  checkHostfxr(code, "unable to load managed assembly")

proc loadAssembly(host: DotnetHost, assemblyBytes: openArray[byte], symbolsBytes: openArray[byte] = []) =
  # Loads an assembly and optional symbols from memory. The buffers are used
  # synchronously; failures raise `DotnetError`.
  requireOpen(host)
  if host.loadAssemblyBytesProc.isNil:
    dotnetError("hostfxr load-assembly-bytes delegate is unavailable", E_NOTIMPL)

  let code = host.loadAssemblyBytesProc(
    addrptr(assemblyBytes), csize_t(assemblyBytes.len),
    addrptr(symbolsBytes), csize_t(symbolsBytes.len), nil, nil)
  checkHostfxr(code, "unable to load managed assembly bytes")

proc load*(assemblyPath, typeName, methodName: string, delegateType = ""): DotnetMethod {.discardable.} =
  ## Loads a static managed method through the current thread's host.
  ##
  ## `delegateType` is a managed delegate type name for non-default
  ## signatures. Pass `UnmanagedCallersOnly` or `"*"` for a method marked
  ## `UnmanagedCallersOnly`; cast the returned address with `asProc[T]` using
  ## the exact ABI.
  load(requireCurrentHost(), assemblyPath, typeName, methodName, delegateType)

proc getMethod*(typeName, methodName: string, delegateType = ""): DotnetMethod {.discardable.} =
  ## Gets a static managed method through the current thread's host.
  ##
  ## `delegateType` follows the rules of `load`; pass `UnmanagedCallersOnly`
  ## or `"*"` for a method marked `UnmanagedCallersOnly`.
  getMethod(requireCurrentHost(), typeName, methodName, delegateType)

proc loadAssembly*(assemblyPath: string) =
  ## Loads an assembly through the current thread's host.
  loadAssembly(requireCurrentHost(), assemblyPath)

proc loadAssembly*(assemblyBytes: openArray[byte],
    symbolsBytes: openArray[byte] = []) =
  ## Loads an assembly from memory through the current thread's host.
  loadAssembly(requireCurrentHost(), assemblyBytes, symbolsBytes)

proc asProc*[T](self: DotnetMethod): T =
  ## Casts the native address to a caller-supplied Nim proc type.
  ##
  ## `T` must use the calling convention and parameter/return layout declared
  ## by the managed delegate passed to `load` or `getMethod`, or by the
  ## unmanaged method's ABI. This cast performs no signature validation.
  if self.address.isNil: dotnetError("managed method pointer is nil", E_POINTER)
  cast[T](self.address)

proc call*(self: DotnetMethod, data: pointer, size: int32): int32 =
  ## Calls a default-signature method with the given buffer.
  if self.address.isNil: dotnetError("managed method pointer is nil", E_POINTER)
  if size < 0: dotnetError("invalid managed length", E_INVALIDARG)
  cast[DotnetComponentEntryPoint](self.address)(data, size)

proc call*(self: DotnetMethod): int32 {.inline.} =
  ## Calls a default-signature method with no data.
  self.call(nil, 0)

proc call*(self: DotnetMethod, data: openArray[byte]): int32 =
  ## Calls a default-signature method with a byte buffer.
  self.call(addrptr(data), checkedInt32Length(data.len))

proc call*(self: DotnetMethod, data: string): int32 =
  ## Calls a default-signature method with the string bytes (no trailing NUL).
  self.call(addrptr(data), checkedInt32Length(data.len))

proc call*[T](self: DotnetMethod, data: var T): int32 =
  ## Calls a default-signature method with the in-memory bytes of `data`.
  self.call(addr data, checkedInt32Length(sizeof(T)))

proc call*[T](self: DotnetMethod, data: T): int32 =
  ## Calls a default-signature method with a copy of `data`.
  var value = data
  self.call(value)

proc toDotnetValue*(x: DotnetValue): DotnetValue {.inline.} =
  ## Returns an already encoded `DotnetValue` unchanged.
  result = x

proc toDotnetValue*(x: typeof(nil)): DotnetValue {.inline.} =
  ## Converts Nim `nil` to a managed null reference.
  DotnetValue(kind: Null)

proc toDotnetValue*(x: bool): DotnetValue {.inline.} =
  ## Converts a Nim Boolean to a managed Boolean value.
  DotnetValue(kind: Bool, boolValue: x)

proc toDotnetValue*(x: string): DotnetValue {.inline.} =
  ## Converts a Nim UTF-8 string to a managed String value.
  DotnetValue(kind: String, stringValue: x)

proc toDotnetValue*(x: cstring): DotnetValue {.inline.} =
  ## Converts a C string to a managed String value.
  toDotnetValue($x)

proc toDotnetValue*(x: char): DotnetValue {.inline.} =
  ## Converts a Nim character to a one-character managed String value.
  toDotnetValue($x)

proc toDotnetValue*(x: int): DotnetValue {.inline.} =
  ## Converts a Nim signed integer to a signed managed numeric value.
  DotnetValue(kind: Int64, int64Value: int64(x))

proc toDotnetValue*(x: int8): DotnetValue {.inline.} =
  ## Converts an 8-bit signed integer to a signed managed numeric value.
  DotnetValue(kind: Int64, int64Value: int64(x))

proc toDotnetValue*(x: int16): DotnetValue {.inline.} =
  ## Converts a 16-bit signed integer to a signed managed numeric value.
  DotnetValue(kind: Int64, int64Value: int64(x))

proc toDotnetValue*(x: int32): DotnetValue {.inline.} =
  ## Converts a 32-bit signed integer to a signed managed numeric value.
  DotnetValue(kind: Int64, int64Value: int64(x))

proc toDotnetValue*(x: int64): DotnetValue {.inline.} =
  ## Converts a 64-bit signed integer to a signed managed numeric value.
  DotnetValue(kind: Int64, int64Value: x)

proc toDotnetValue*(x: uint): DotnetValue {.inline.} =
  ## Converts a Nim unsigned integer to an unsigned managed numeric value.
  DotnetValue(kind: UInt64, uint64Value: uint64(x))

proc toDotnetValue*(x: uint8): DotnetValue {.inline.} =
  ## Converts an 8-bit unsigned integer to an unsigned managed numeric value.
  DotnetValue(kind: UInt64, uint64Value: uint64(x))

proc toDotnetValue*(x: uint16): DotnetValue {.inline.} =
  ## Converts a 16-bit unsigned integer to an unsigned managed numeric value.
  DotnetValue(kind: UInt64, uint64Value: uint64(x))

proc toDotnetValue*(x: uint32): DotnetValue {.inline.} =
  ## Converts a 32-bit unsigned integer to an unsigned managed numeric value.
  DotnetValue(kind: UInt64, uint64Value: uint64(x))

proc toDotnetValue*(x: uint64): DotnetValue {.inline.} =
  ## Converts a 64-bit unsigned integer to an unsigned managed numeric value.
  DotnetValue(kind: UInt64, uint64Value: x)

proc toDotnetValue*(x: float32): DotnetValue {.inline.} =
  ## Converts a 32-bit float to a managed double-compatible numeric value.
  DotnetValue(kind: Float64, float64Value: float64(x))

proc toDotnetValue*(x: float64): DotnetValue {.inline.} =
  ## Converts a Nim float to a managed floating-point value.
  DotnetValue(kind: Float64, float64Value: x)

proc toDotnetValue*(x: DotnetObject): DotnetValue {.inline.} =
  ## Converts a managed object handle; nil handles become managed null.
  if x.isNil or x.handle.isNil: DotnetValue(kind: Null)
  else: DotnetValue(kind: Object, objectValue: x)

proc appendByte(data: var seq[byte], value: byte) =
  data.add value

proc appendInt32(data: var seq[byte], value: int32) =
  let oldLen = data.len
  data.setLen(oldLen + sizeof(value))
  copyMem(addr data[oldLen], unsafeAddr value, sizeof(value))

proc appendInt64(data: var seq[byte], value: int64) =
  let oldLen = data.len
  data.setLen(oldLen + sizeof(value))
  copyMem(addr data[oldLen], unsafeAddr value, sizeof(value))

proc appendPointer(data: var seq[byte], value: pointer) =
  appendInt64(data, cast[int64](cast[uint](value)))

proc appendString(data: var seq[byte], value: string) =
  appendInt32(data, checkedInt32Length(value.len))
  if value.len == 0: return

  let oldLen = data.len
  data.setLen(oldLen + value.len)
  copyMem(addr data[oldLen], unsafeAddr value[0], value.len)

proc appendDotnetValue(data: var seq[byte], value: DotnetValue) =
  appendByte(data, byte(value.kind))
  case value.kind
  of Null: discard
  of Bool: appendByte(data, if value.boolValue: 1'u8 else: 0'u8)
  of Int64: appendInt64(data, value.int64Value)
  of UInt64: appendInt64(data, cast[int64](value.uint64Value))
  of String: appendString(data, value.stringValue)
  of Float64:
    var bits: int64
    copyMem(addr bits, unsafeAddr value.float64Value, sizeof(bits))
    appendInt64(data, bits)
  of Object:
    if value.objectValue.isNil or value.objectValue.handle.isNil: appendInt64(data, 0)
    else: appendPointer(data, value.objectValue.handle)

proc readInt32(data: openArray[byte], offset: int): int32 =
  if offset < 0 or offset > data.len - sizeof(result):
    dotnetError("managed operation failed", E_UNEXPECTED)

  copyMem(addr result, unsafeAddr data[offset], sizeof(result))

proc readInt64(data: openArray[byte], offset: int): int64 =
  if offset < 0 or offset > data.len - sizeof(result):
    dotnetError("managed operation failed", E_UNEXPECTED)

  copyMem(addr result, unsafeAddr data[offset], sizeof(result))

proc readBridgeString(response: openArray[byte], offset: var int): string =
  let length = int(readInt32(response, offset))
  offset += sizeof(int32)

  if length < 0 or offset > response.len or length > response.len - offset:
    dotnetError("managed operation failed", E_UNEXPECTED)

  if length != 0:
    result = newString(length)
    copyMem(addr result[0], unsafeAddr response[offset], length)

  offset += length

proc readBridgeError(response: openArray[byte]): string =
  var offset = 0
  discard readBridgeString(response, offset)
  result = readBridgeString(response, offset)
  if offset != response.len: dotnetError("managed operation failed", E_UNEXPECTED)
  if result.len == 0: result = "managed object operation failed"

proc bridgeAssemblyPath(host: DotnetHost, name: string): string =
  let expectedName = extractFilename(name)
  for frameworkPath in host.frameworkPaths:
    let path = frameworkPath / expectedName
    if fileExists(path): return path

  dotnetError("modern .NET assembly was not found: " & name)

proc ensureDelegateBridge(host: DotnetHost) =
  requireOpen(host)
  if host.delegateBridgeLoaded: return

  let assemblyBytes = DotnetDelegateBridgeAssemblyBase64.decode
  if assemblyBytes.len == 0:
    dotnetError("managed delegate bridge assembly is empty", E_UNEXPECTED)

  loadAssembly(host, assemblyBytes.toOpenArrayByte(0, assemblyBytes.len - 1))
  host.delegateBridgeLoaded = true

proc ensureObjectBridge(host: DotnetHost) =
  requireOpen(host)
  if not host.objectBridgeMethod.isNil: return
  if host.loadAssemblyBytesProc.isNil:
    dotnetError("managed object APIs require .NET 8+ hostfxr load_assembly_bytes capability", E_NOTIMPL)

  let assemblyBytes = DotnetObjectBridgeAssemblyBase64.decode
  if assemblyBytes.len == 0:
    dotnetError("managed operation failed", E_UNEXPECTED)

  loadAssembly(host, assemblyBytes.toOpenArrayByte(0, assemblyBytes.len - 1))
  host.objectBridgeMethod = getMethod(host,
    "WinimDotnetBridge.Bridge, " & DotnetObjectBridgeAssemblyName,
    "Invoke").address

proc bridgeOperation(host: DotnetHost, operation: DotnetBridgeOperation,
    target: pointer, typeName, memberName: string,
    args: openArray[DotnetValue] = []): seq[byte] {.discardable.} =
  requireOpen(host)
  ensureObjectBridge(host)
  var
    descriptor: DotnetBridgeResponseDescriptor
    request: seq[byte]
  defer:
    if not descriptor.data.isNil: CoTaskMemFree(descriptor.data)

  appendByte(request, byte(operation))
  appendPointer(request, addr descriptor)
  appendPointer(request, target)
  appendString(request, typeName)
  appendString(request, memberName)
  appendInt32(request, checkedInt32Length(args.len))
  for arg in args:
    appendDotnetValue(request, arg)

  let
    entry = cast[DotnetComponentEntryPoint](host.objectBridgeMethod)
    requestLength = checkedInt32Length(request.len)
    code = entry(cast[pointer](addr request[0]), requestLength)
  if code != 0: dotnetError("managed operation failed", code)

  if descriptor.length < 0 or (descriptor.length != 0 and descriptor.data.isNil):
    dotnetError("managed operation failed", E_UNEXPECTED)

  let responseLength = int(descriptor.length)
  if responseLength != 0:
    result = newSeq[byte](responseLength)
    copyMem(addr result[0], descriptor.data, responseLength)

  if descriptor.status != 0:
    dotnetError(readBridgeError(result), descriptor.status)

proc releaseDotnetObjects(host: DotnetHost) =
  if host.isNil or host.managedHandles.len == 0: return

  var handles: seq[pointer]
  for handle in host.managedHandles.keys:
    handles.add handle

  host.managedHandles.clear()
  var firstError: ref Exception
  for handle in handles:
    try:
      bridgeOperation(host, releaseHandle, handle, "", "")
    except Exception:
      if firstError.isNil: firstError = getCurrentException()

  if not firstError.isNil: raise firstError

proc releaseManagedHandle(host: DotnetHost, handle: pointer, owned: bool) =
  if host.isNil or handle.isNil: return
  try:
    if host.managedHandles.hasKey(handle): host.managedHandles.del(handle)
    if owned and not host.closed and not host.context.isNil:
      bridgeOperation(host, releaseHandle, handle, "", "")
  except CatchableError: discard

proc releaseDotnetHandle(self: var DotnetObjectData) =
  if self.handle.isNil: return
  let
    handle = self.handle
    host = self.host
    owned = self.owned
  self.handle = nil
  self.owned = false
  releaseManagedHandle(host, handle, owned)

proc release*(self: DotnetObject) =
  ## Releases the managed handle immediately; nil and released objects are
  ## ignored.
  if self.isNil: return
  releaseDotnetHandle(self[])

proc release(objs: varargs[DotnetObject]) =
  for obj in objs:
    obj.release()

when not defined(gcDestructors):
  proc finalizeDotnetObject(self: DotnetObject) =
    if not self.isNil: releaseDotnetHandle(self[])

proc newDotnetObject(host: DotnetHost, handle: pointer, owned: bool): DotnetObject =
  when defined(gcDestructors):
    system.new(result)
  else:
    system.new(result, finalizeDotnetObject)
  result.handle = handle
  result.host = host
  result.owned = owned
  if not host.isNil and not handle.isNil:
    host.managedHandles[handle] = true

proc objectFromHandle(host: DotnetHost, handle: int64, owned = true): DotnetObject =
  if handle == 0: return
  result = newDotnetObject(host, cast[pointer](handle), owned)

proc objectFromResponse(host: DotnetHost, response: openArray[byte]): DotnetObject =
  objectFromHandle(host, readInt64(response, 0))

proc requireObject(self: DotnetObject): DotnetHost {.discardable.} =
  if self.isNil or self.handle.isNil:
    dotnetError("managed object is nil", E_POINTER)

  result = self.host
  requireOpen(result)

proc requireObjectValue(value: DotnetValue, host: DotnetHost) =
  if value.kind != Object: return
  if value.objectValue.isNil or value.objectValue.handle.isNil: return
  if value.objectValue.host != host:
    dotnetError("managed objects belong to different hosts", E_INVALIDARG)

proc newObject(host: DotnetHost, typeName: string,
    args: varargs[DotnetValue, toDotnetValue]): DotnetObject {.discardable.} =
  ## Creates a managed object through `Activator.CreateInstance`.
  ##
  ## `typeName` may be a full type name or an assembly-qualified name such as
  ## `System.Text.StringBuilder, System.Private.CoreLib`. Constructor
  ## overload resolution is performed by the managed bridge using `args`.
  ## Primitive Nim arguments are converted by `toDotnetValue`; existing
  ## `DotnetObject` values are passed as managed object arguments.
  requireOpen(host)
  var values = newSeq[DotnetValue](args.len)
  for i, arg in args:
    values[i] = arg
  let response = bridgeOperation(host, create, nil, typeName, "", values)
  objectFromResponse(host, response)

proc newClass(host: DotnetHost, typeName: string, assemblyName = ""): DotnetClass =
  ## Creates a type proxy for constructors and static members.
  ##
  ## `assemblyName` makes type resolution deterministic and is combined with
  ## `typeName` unless `typeName` is already assembly-qualified. This call does
  ## not construct a managed object; use `new`, `newObject`, or a static member
  ## operation on the returned proxy.
  requireOpen(host)
  result = DotnetClass(host: host, typeName: typeName, assemblyName: assemblyName)

proc qualifiedTypeName(typ: DotnetClass): string =
  if typ.assemblyName.len == 0 or typ.typeName.contains(','): return typ.typeName
  return typ.typeName & ", " & typ.assemblyName

proc newObject*(typ: DotnetClass, args: varargs[DotnetValue, toDotnetValue]): DotnetObject {.discardable.} =
  ## Creates an instance represented by `typ`; arguments use managed overload
  ## resolution.
  if typ.isNil: dotnetError("managed class is nil", E_POINTER)

  var values = newSeq[DotnetValue](args.len)
  for i, arg in args:
    values[i] = arg

  let response = bridgeOperation(typ.host, create, nil, qualifiedTypeName(typ), "", values)
  return objectFromResponse(typ.host, response)

proc new*(typ: DotnetClass, args: varargs[DotnetValue, toDotnetValue]): DotnetObject {.discardable.} =
  ## Convenience alias for `newObject(typ, args)`.
  return newObject(typ, args)

proc load(host: DotnetHost, assemblyName: string): DotnetAssembly {.discardable.} =
  ## Loads a framework or file assembly for type lookup.
  ## Framework names are resolved from the active shared framework; paths are
  ## loaded directly. Use the result with `new` or `getType`.
  requireOpen(host)
  var path = assemblyName
  if not fileExists(path):
    var fileName = assemblyName
    if not fileName.toLowerAscii.endsWith ".dll": fileName.add ".dll"
    path = bridgeAssemblyPath(host, fileName)

  let lowerName = extractFilename(path).toLowerAscii
  if lowerName notin ["system.private.corelib.dll", "system.runtime.dll"]:
    loadAssembly(host, path)

  return DotnetAssembly(host: host, path: absolutePath(path), name: splitFile(path).name)

proc getType*(assembly: DotnetAssembly, typeName: string): DotnetClass =
  ## Creates a type proxy for `typeName`; lookup is deferred until use.
  if assembly.isNil: dotnetError("managed assembly is nil", E_POINTER)
  return DotnetClass(host: assembly.host, typeName: typeName, assemblyName: assembly.name)

proc new*(assembly: DotnetAssembly, typeName: string,
    args: varargs[DotnetValue, toDotnetValue]): DotnetObject {.discardable.} =
  ## Creates an object from a type in `assembly`.
  return newObject(assembly.getType(typeName), args)

proc loadClass(host: DotnetHost, typeName: string;
    assemblyName = ""): DotnetClass =
  ## Creates a type proxy without a `DotnetAssembly` value. `assemblyName`
  ## optionally makes type resolution deterministic.
  if assemblyName.len == 0: return newClass(host, typeName)

  discard load(host, assemblyName)
  let loadedName =
    if assemblyName.toLowerAscii.endsWith ".dll": splitFile(assemblyName).name
    else: assemblyName

  return newClass(host, typeName, loadedName)

proc enumValue(host: DotnetHost, typeName, value: string): DotnetObject =
  ## Creates a boxed enum value for a property or method argument.
  let response = bridgeOperation(host, boxEnum, nil, typeName, value)
  return objectFromResponse(host, response)

proc newObject*(typeName: string,
    args: varargs[DotnetValue, toDotnetValue]): DotnetObject {.discardable.} =
  ## Creates a managed object through the current thread's host.
  newObject(requireCurrentHost(), typeName, args)

proc newClass*(typeName: string, assemblyName = ""): DotnetClass =
  ## Creates a type proxy through the current thread's host.
  newClass(requireCurrentHost(), typeName, assemblyName)

proc load*(assemblyName: string): DotnetAssembly {.discardable.} =
  ## Loads a framework or file assembly through the current thread's host.
  load(requireCurrentHost(), assemblyName)

proc loadClass*(typeName: string; assemblyName = ""): DotnetClass =
  ## Creates a type proxy through the current thread's host.
  loadClass(requireCurrentHost(), typeName, assemblyName)

proc enumValue*(typeName, value: string): DotnetObject =
  ## Creates a boxed enum value through the current thread's host.
  enumValue(requireCurrentHost(), typeName, value)

proc dotnetGet*(self: DotnetObject, name: string): DotnetObject =
  ## Gets an instance property or field by name.
  let host = requireObject(self)
  let response = bridgeOperation(host, get, self.handle, "", name)
  return objectFromResponse(host, response)

proc dotnetSet*[T](self: DotnetObject, name: string, value: T) =
  ## Sets an instance property or field by name.
  let host = requireObject(self)
  let encoded = toDotnetValue(value)
  if encoded.kind == Object: requireObjectValue(encoded, host)
  bridgeOperation(host, setValue, self.handle, "", name, [encoded])

proc dotnetInvoke*(self: DotnetObject, name: string,
    args: varargs[DotnetValue, toDotnetValue]): DotnetObject {.discardable.} =
  ## Invokes an instance method by name and returns its result.
  let host = requireObject(self)
  var values = newSeq[DotnetValue](args.len)
  for i, arg in args:
    values[i] = arg
    if arg.kind == Object: requireObjectValue(arg, host)

  let response = bridgeOperation(host, invoke, self.handle, "", name, values)
  return objectFromResponse(host, response)

proc dotnetGet*(typ: DotnetClass, name: string): DotnetObject =
  ## Gets a static property or field from a managed type proxy.
  if typ.isNil: dotnetError("managed class is nil", E_POINTER)
  let host = typ.host
  let response = bridgeOperation(host, staticGet, nil, qualifiedTypeName(typ), name)
  return objectFromResponse(host, response)

proc dotnetSet*[T](typ: DotnetClass, name: string, value: T) =
  ## Sets a static property or field on a managed type proxy.
  if typ.isNil: dotnetError("managed class is nil", E_POINTER)
  let encoded = toDotnetValue(value)
  if encoded.kind == Object: requireObjectValue(encoded, typ.host)
  bridgeOperation(typ.host, staticSet, nil, qualifiedTypeName(typ), name, [encoded])

proc dotnetInvoke*(typ: DotnetClass, name: string,
    args: varargs[DotnetValue, toDotnetValue]): DotnetObject {.discardable.} =
  ## Invokes a static method on a managed type proxy.
  if typ.isNil: dotnetError("managed class is nil", E_POINTER)
  var values = newSeq[DotnetValue](args.len)
  for i, arg in args:
    values[i] = arg
    if arg.kind == Object: requireObjectValue(arg, typ.host)

  let response = bridgeOperation(typ.host, staticInvoke, nil, qualifiedTypeName(typ), name, values)
  return objectFromResponse(typ.host, response)

proc getProperty*(self: DotnetObject, name: string): DotnetObject =
  ## Explicit API alias for `dotnetGet` on an instance object.
  return dotnetGet(self, name)

proc setProperty*[T](self: DotnetObject, name: string, value: T) =
  ## Explicit API alias for `dotnetSet` on an instance object.
  dotnetSet(self, name, value)

proc invoke*(self: DotnetObject, name: string, args: varargs[DotnetValue, toDotnetValue]): DotnetObject {.discardable.} =
  ## Explicit API alias for `dotnetInvoke` on an instance object.
  return dotnetInvoke(self, name, args)

proc `[]`*(self: DotnetObject, index: SomeOrdinal): DotnetObject {.discardable.} =
  ## Gets a value through a managed ordinal indexer, such as `items[0]`.

  # Keep a precise one-ordinal overload in addition to the general varargs form.
  # Nim 2.0 can otherwise see `system.[](string, int)` through the exported
  # DotnetObject-to-string converter and report an ambiguity for `items[0]`.
  return dotnetInvoke(self, "get_Item", index)

proc `[]`*(self: DotnetObject, args: varargs[DotnetValue, toDotnetValue]):
    DotnetObject {.discardable.} =
  ## Gets a value through a managed indexer with arbitrary arguments.
  return dotnetInvoke(self, "get_Item", args)

proc `[]=`*[T](self: DotnetObject, index: SomeOrdinal, value: T) {.discardable.} =
  ## Sets a value through a managed ordinal indexer, such as `items[0] = value`.
  dotnetInvoke(self, "set_Item", index, value)

proc `[]=`*(self: DotnetObject, args: varargs[DotnetValue, toDotnetValue]) {.discardable.} =
  ## Sets a value through a managed indexer with arbitrary arguments.
  if args.len < 2:
    dotnetError("managed indexer requires an index and a value", E_INVALIDARG)
  dotnetInvoke(self, "set_Item", args)

proc getProperty*(typ: DotnetClass, name: string): DotnetObject =
  ## Explicit API alias for `dotnetGet` on a static type proxy.
  return dotnetGet(typ, name)

proc setProperty*[T](typ: DotnetClass, name: string, value: T) =
  ## Explicit API alias for `dotnetSet` on a static type proxy.
  dotnetSet(typ, name, value)

proc invoke*(typ: DotnetClass, name: string, args: varargs[DotnetValue, toDotnetValue]): DotnetObject {.discardable.} =
  ## Explicit API alias for `dotnetInvoke` on a static type proxy.
  return dotnetInvoke(typ, name, args)

proc nextDotnetEventId(): uint64 =
  while true:
    let candidate = InterlockedIncrement64(addr NextDotnetEventId)
    if candidate > 0 and not DotnetEventRegistrations.hasKey(uint64(candidate)):
      return uint64(candidate)

proc on*(self: DotnetObject, eventName: string, handler: DotnetEventHandler): DotnetEventToken {.discardable.} =
  ## Registers one Nim callback and returns its opaque removal token.
  ## Invoke pending callbacks on the registering thread with `pollEvents`.
  let host = requireObject(self)
  if handler.isNil: dotnetError("managed event handler is nil", E_POINTER)

  var registration = DotnetEventRegistration(
    host: host,
    target: self,
    eventName: eventName,
    handler: handler)
  let eventId = nextDotnetEventId()
  registration.eventId = eventId

  DotnetEventRegistrations[eventId] = registration
  try:
    discard bridgeOperation(host, addEvent, self.handle, $eventId, eventName)
  except CatchableError:
    DotnetEventRegistrations.del(eventId)
    raise
  return DotnetEventToken(host: host, eventId: eventId)

proc pollEvents(host: DotnetHost): int {.discardable.} =
  ## Executes queued handlers on the registering thread and returns the number
  ## actually invoked; stale queued events do not increase the result.
  requireOpen(host)
  var
    response: seq[byte]
    eventKey: uint64
    sender, args: DotnetObject
    registration: DotnetEventRegistration
  defer:
    release(sender, args)

  while true:
    response = bridgeOperation(host, pollEvent, nil, "", "")
    let eventId = readInt64(response, 16)
    if eventId == 0: break
    eventKey = cast[uint64](eventId)
    sender = objectFromHandle(host, readInt64(response, 0))
    args = objectFromHandle(host, readInt64(response, 8))

    registration =
      if DotnetEventRegistrations.hasKey(eventKey) and
          DotnetEventRegistrations[eventKey].host == host:
        DotnetEventRegistrations[eventKey]
      else: nil
    if not registration.isNil:
      inc result
      registration.handler(sender, args)

proc pollApplicationEvents(hwnd: HWND, message: UINT, timerId: UINT_PTR, timestamp: DWORD) {.stdcall.} =
  if not DotnetApplicationRunStates.hasKey(timerId): return
  let state = DotnetApplicationRunStates[timerId]
  if state.isNil or state.host.isNil or
    state.host.closed or not state.pendingException.isNil: return

  try:
    pollEvents(state.host)
    if hasPendingOperations(): poll(0)

  except CatchableError:
    state.pendingException = getCurrentException()
    try: dotnetInvoke(state.application, "ExitThread")
    except CatchableError: PostQuitMessage(0)

proc runApplicationWithEvents(host: DotnetHost, application: DotnetClass, form: DotnetObject) =
  # Internal implementation for `Application.Run(form)`.
  #
  # The timer is created on the current thread, so its callback runs on the
  # same UI thread as `Application.Run`. This keeps both WinForms controls
  # and Nim event handlers on the thread that owns the message loop.
  requireOpen(host)
  let
    state = DotnetApplicationRunState(host: host, application: application)
    timerId = SetTimer(0, 0, 10, pollApplicationEvents)
  if timerId == 0: raise newException(OSError, "SetTimer failed")

  if DotnetApplicationRunStates.hasKey(timerId):
    KillTimer(0, timerId)
    raise newException(OSError, "SetTimer returned a duplicate timer id")

  DotnetApplicationRunStates[timerId] = state
  try:
    discard dotnetInvoke(application, "Run", form)
  finally:
    KillTimer(0, timerId)
    DotnetApplicationRunStates.del(timerId)

  if state.pendingException.isNil and not host.closed:
    pollEvents(host)

  if not state.pendingException.isNil:
    raise state.pendingException

proc pollEvents*(): int {.discardable.} =
  ## Executes queued handlers for the current thread's host.
  pollEvents(requireCurrentHost())

proc runStaticApplication(typ: DotnetClass, form: DotnetObject): DotnetObject {.discardable.} =
  let isWinFormsApplication = not typ.isNil and
    (typ.typeName == "System.Windows.Forms.Application" or
      typ.typeName.startsWith("System.Windows.Forms.Application,")) and
    (typ.assemblyName.len == 0 or
      typ.assemblyName == "System.Windows.Forms")
  if isWinFormsApplication:
    runApplicationWithEvents(typ.host, typ, form)
    return
  dotnetInvoke(typ, "Run", form)

proc clearDotnetEvents(host: DotnetHost) =
  var ids: seq[uint64]
  for id, registration in DotnetEventRegistrations:
    if registration.host == host: ids.add id

  var firstError: ref Exception
  for id in ids:
    try:
      discard bridgeOperation(host, clearEvents, nil, "", $id)
      DotnetEventRegistrations.del(id)
    except Exception:
      if firstError.isNil: firstError = getCurrentException()

  if not firstError.isNil: raise firstError

proc `$`*(self: DotnetObject): string =
  ## Returns the managed object's `ToString()` value; nil objects become
  ## `"null"`.
  if self.isNil or self.handle.isNil: return "null"

  let
    response = bridgeOperation(self.host, convertToString, self.handle, "", "")
    length = int(readInt32(response, 0))
  if length <= 0: return ""
  if response.len < 4 or length > response.len - 4: dotnetError("managed operation failed", E_UNEXPECTED)

  result = newString(length)
  copyMem(addr result[0], unsafeAddr response[4], length)

proc toInt64*(self: DotnetObject): int64 =
  ## Converts a managed value to `int64`.
  let response = bridgeOperation(requireObject(self), convertToInt64, self.handle, "", "")
  return readInt64(response, 0)

proc toInt*(self: DotnetObject): int =
  ## Converts a managed value to platform `int`.
  return int(self.toInt64)

proc toBool*(self: DotnetObject): bool =
  ## Converts a managed value to Nim `bool`.
  let response = bridgeOperation(requireObject(self), convertToBool, self.handle, "", "")
  return readInt32(response, 0) != 0

# Keep this async declaration before the public `off` overloads below. Nim 2.0
# asyncmacro emits `stackTrace: off` with an unqualified `off`; if this module's
# `off` proc is already declared, Nim 2.0 resolves that name to the proc and
# fails with "got 'None' for 'off' but expected 'bool'". Newer Nim versions are
# not affected, but winim supports Nim 2.0.
proc toFuture*(task: DotnetObject, pollIntervalMs = 10): Future[DotnetObject] {.async.} =
  ## Waits for a managed `Task` or `ValueTask` without blocking the Nim async
  ## dispatcher.
  ##
  ## The returned object is the value of `Task<T>.Result` or
  ## `ValueTask<T>.Result`. A non-generic awaitable completes with a nil result.
  ## The awaitable and its host must remain alive until the returned Future
  ## completes.
  requireObject(task)
  let delay = if pollIntervalMs < 1: 1 else: pollIntervalMs
  var completed, canceled, faulted, exception, taskType, resultProperty: DotnetObject
  defer: release(resultProperty, taskType, exception, faulted, canceled, completed)

  while true:
    completed = dotnetGet(task, "IsCompleted")
    if completed.toBool: break
    await sleepAsync(delay)

  canceled = dotnetGet(task, "IsCanceled")
  if canceled.toBool: raise newException(DotnetTaskCanceledError, "managed task was canceled")

  faulted = dotnetGet(task, "IsFaulted")
  if faulted.toBool:
    exception = dotnetGet(task, "Exception")
    let message = if exception.isNil: "managed task failed" else: $exception
    raise newException(DotnetError, message)

  taskType = dotnetInvoke(task, "GetType")

  resultProperty = dotnetInvoke(taskType, "GetProperty", "Result")
  if resultProperty.isNil: return

  return resultProperty.dotnetInvoke("GetValue", task)

proc off*(token: DotnetEventToken): bool {.discardable.} =
  ## Removes exactly the registration represented by `token`.
  ## Returns `false` when it was already removed or is used on another thread.
  if token.eventId == 0 or not DotnetEventRegistrations.hasKey(token.eventId): return false
  let registration = DotnetEventRegistrations[token.eventId]
  if registration.host != token.host: return false

  bridgeOperation(registration.host, removeEvent, registration.target.handle,
    $registration.eventId, registration.eventName)
  DotnetEventRegistrations.del(token.eventId)
  return true

proc off*(self: DotnetObject, eventName: string): int {.discardable.} =
  ## Removes all case-insensitive matching registrations on the registering
  ## thread and returns the count.
  let host = requireObject(self)
  var eventIds: seq[uint64]
  for id, registration in DotnetEventRegistrations:
    if registration.host == host and registration.target == self and
        registration.eventName.toLowerAscii == eventName.toLowerAscii:
      eventIds.add id

  var firstError: ref Exception
  for eventId in eventIds:
    let registration = DotnetEventRegistrations[eventId]
    try:
      bridgeOperation(host, removeEvent, self.handle, $eventId, registration.eventName)
      DotnetEventRegistrations.del(eventId)
      inc result
    except Exception:
      if firstError.isNil: firstError = getCurrentException()

  if not firstError.isNil: raise firstError

proc getManagedType(host: DotnetHost, assemblyQualifiedName: string): DotnetObject =
  ## Returns a managed `System.Type` object for an assembly-qualified name.
  ##
  ## This is useful when an API needs a runtime type object rather than a
  ## `DotnetClass` proxy, for example when constructing expressions or
  ## delegates through `System.Linq.Expressions`.
  requireOpen(host)
  let typeClass = loadClass(host, "System.Type", "System.Private.CoreLib")
  return dotnetInvoke(typeClass, "GetType", assemblyQualifiedName)

proc clearDotnetDelegates(host: DotnetHost) =
  acquire(DotnetDelegateLock)
  defer: release(DotnetDelegateLock)

  var contexts: seq[pointer]
  for context, registration in DotnetDelegateRegistrations:
    if registration.host == host:
      contexts.add context
  for context in contexts:
    DotnetDelegateRegistrations.del(context)

proc newManagedArray(host: DotnetHost, elementType: DotnetObject,
    values: openArray[DotnetObject]): DotnetObject =
  ## Creates a managed one-dimensional array with the requested element type.
  ##
  ## The values may be managed objects from `host`; a nil value represents a
  ## null managed reference.
  requireOpen(host)
  if requireObject(elementType) != host:
    dotnetError("managed array element type belongs to a different host", E_INVALIDARG)

  for value in values:
    if not value.isNil and requireObject(value) != host:
      dotnetError("managed array value belongs to a different host", E_INVALIDARG)

  let arrayClass = loadClass(host, "System.Array", "System.Private.CoreLib")
  result = dotnetInvoke(arrayClass, "CreateInstance", elementType, values.len)

  for index, value in values:
    dotnetInvoke(result, "SetValue", value, index)

proc duplicateManagedHandle(host: DotnetHost, handle: pointer): pointer =
  if handle.isNil: return
  var
    gcHandleClass: DotnetClass
    handlePointer, managedHandle, target, allocatedHandle, pointerValue, pointerInteger: DotnetObject
  defer:
    release(pointerInteger, pointerValue, allocatedHandle, target, managedHandle, handlePointer)

  gcHandleClass = loadClass(host, "System.Runtime.InteropServices.GCHandle", "System.Private.CoreLib")
  handlePointer = newObject(host, "System.IntPtr", cast[int64](handle))
  managedHandle = dotnetInvoke(gcHandleClass, "FromIntPtr", handlePointer)
  target = dotnetGet(managedHandle, "Target")
  allocatedHandle = dotnetInvoke(gcHandleClass, "Alloc", target)
  pointerValue = dotnetInvoke(gcHandleClass, "ToIntPtr", allocatedHandle)
  pointerInteger = dotnetInvoke(pointerValue, "ToInt64")
  return cast[pointer](pointerInteger.toInt64)

proc dotnetDelegateEntryPoint(context, arguments: pointer): pointer {.stdcall.} =
  var
    registration: DotnetDelegateRegistration
    rawArguments: ptr UncheckedArray[pointer]
    parameterCount: int
    statusSlot: int
    managedArguments: seq[DotnetObject]
    handlePointer, handle, value, errorValue: DotnetObject
  defer:
    release(errorValue, value, handle, handlePointer)
    managedArguments.release()

  acquire(DotnetDelegateLock)
  if DotnetDelegateRegistrations.hasKey(context):
    registration = DotnetDelegateRegistrations[context]
  release(DotnetDelegateLock)

  if registration.isNil or registration.host.isNil or arguments.isNil: return
  rawArguments = cast[ptr UncheckedArray[pointer]](arguments)
  parameterCount = cast[int](rawArguments[0])
  statusSlot = parameterCount + 1
  rawArguments[statusSlot] = nil

  if registration.host.ownerThreadId != GetCurrentThreadId() or parameterCount != registration.parameterCount:
    rawArguments[statusSlot] = cast[pointer](1)
    return

  try:
    let host = registration.host
    requireOpen(host)
    let gcHandleClass = loadClass(host, "System.Runtime.InteropServices.GCHandle", "System.Private.CoreLib")

    for index in 0 ..< parameterCount:
      let rawArgument = rawArguments[index + 1]
      if rawArgument.isNil:
        managedArguments.add nil
        continue

      handlePointer = newObject(host, "System.IntPtr", cast[int64](rawArgument))
      handle = dotnetInvoke(gcHandleClass, "FromIntPtr", handlePointer)
      managedArguments.add dotnetGet(handle, "Target")

    value = registration.callback(managedArguments)
    if value.isNil: return
    return duplicateManagedHandle(host, value.handle)
  except Exception:
    rawArguments[statusSlot] = cast[pointer](1)
    try:
      let stringClass = loadClass(registration.host, "System.String", "System.Private.CoreLib")
      errorValue = dotnetInvoke(stringClass, "Concat", getCurrentExceptionMsg())
      return duplicateManagedHandle(registration.host, errorValue.handle)
    except Exception:
      discard

proc newDelegate(host: DotnetHost, delegateType: DotnetObject, parameters: openArray[DotnetObject], body: DotnetObject): DotnetObject =
  requireOpen(host)
  if requireObject(delegateType) != host: dotnetError("managed delegate type belongs to a different host", E_INVALIDARG)
  if requireObject(body) != host: dotnetError("managed delegate body belongs to a different host", E_INVALIDARG)

  for parameter in parameters:
    if parameter.isNil or requireObject(parameter) != host:
      dotnetError("managed delegate parameter is invalid", E_INVALIDARG)

  var
    expressionClass: DotnetClass
    parameterExpressionType, parameterArray, lambda: DotnetObject
  defer:
    release(lambda, parameterArray, parameterExpressionType)

  expressionClass = loadClass(host, "System.Linq.Expressions.Expression", "System.Linq.Expressions")
  parameterExpressionType = getManagedType(host, "System.Linq.Expressions.ParameterExpression, System.Linq.Expressions")
  parameterArray = newManagedArray(host, parameterExpressionType, parameters)
  lambda = dotnetInvoke(expressionClass, "Lambda", delegateType, body, parameterArray)
  result = dotnetInvoke(lambda, "Compile")

proc newDelegate(host: DotnetHost, delegateType: DotnetObject, bodyBuilder: DotnetDelegateBodyBuilder): DotnetObject =
  requireOpen(host)
  if requireObject(delegateType) != host: dotnetError("managed delegate type belongs to a different host", E_INVALIDARG)
  if bodyBuilder.isNil: dotnetError("managed delegate body builder is nil", E_POINTER)

  var
    expressionClass: DotnetClass
    invokeMethod, parameterInfos, length, parameterInfo, parameterType, body: DotnetObject
    parameters: seq[DotnetObject]
  defer:
    release(body, parameterType, parameterInfo, length, parameterInfos, invokeMethod)
    parameters.release()

  expressionClass = loadClass(host, "System.Linq.Expressions.Expression", "System.Linq.Expressions")
  invokeMethod = dotnetInvoke(delegateType, "GetMethod", "Invoke")
  parameterInfos = dotnetInvoke(invokeMethod, "GetParameters")
  length = dotnetGet(parameterInfos, "Length")

  for index in 0 ..< length.toInt:
    parameterInfo = dotnetInvoke(parameterInfos, "GetValue", index)
    parameterType = dotnetGet(parameterInfo, "ParameterType")
    parameters.add(dotnetInvoke(expressionClass, "Parameter", parameterType, "arg" & $index))

  body = bodyBuilder(expressionClass, parameters)
  result = newDelegate(host, delegateType, parameters, body)

proc newDelegate(host: DotnetHost, delegateType: DotnetObject, callback: DotnetDelegateCallback): DotnetObject =
  requireOpen(host)
  if requireObject(delegateType) != host: dotnetError("managed delegate type belongs to a different host", E_INVALIDARG)
  if callback.isNil: dotnetError("managed delegate callback is nil", E_POINTER)

  var
    invokeMethod, returnType, returnIsByRef, returnIsPointer, returnIsByRefLike,
      parameterInfos, length, parameterInfo, parameterType, isByRef, isPointer,
      isByRefLike, expressionType, objectType, bridgeType, nativeDelegateType,
      callbackPointer, nativeDelegate, contextValue, returnTypeName: DotnetObject
    marshalClass: DotnetClass
    bodyBuilder: DotnetDelegateBodyBuilder
    registration: DotnetDelegateRegistration
    context: pointer
    parameterCount: int
    invokeName: string
    registrationAdded = false
  defer:
    release(returnTypeName, contextValue, nativeDelegate, callbackPointer,
      nativeDelegateType, bridgeType, expressionType, objectType, isByRefLike,
      isPointer, isByRef, parameterType, parameterInfo, length, parameterInfos,
      returnIsByRefLike, returnIsPointer, returnIsByRef, returnType, invokeMethod)
    if registrationAdded:
      acquire(DotnetDelegateLock)
      if DotnetDelegateRegistrations.hasKey(context):
        DotnetDelegateRegistrations.del(context)
      release(DotnetDelegateLock)

  invokeMethod = dotnetInvoke(delegateType, "GetMethod", "Invoke")
  returnType = dotnetGet(invokeMethod, "ReturnType")
  returnIsByRef = dotnetGet(returnType, "IsByRef")
  returnIsPointer = dotnetGet(returnType, "IsPointer")
  returnIsByRefLike = dotnetGet(returnType, "IsByRefLike")
  if returnIsByRef.toBool or returnIsPointer.toBool or returnIsByRefLike.toBool:
    dotnetError("callable bridge does not support byref, pointer, or byref-like return types", E_INVALIDARG)

  parameterInfos = dotnetInvoke(invokeMethod, "GetParameters")
  length = dotnetGet(parameterInfos, "Length")
  parameterCount = length.toInt

  for index in 0 ..< parameterCount:
    parameterInfo = dotnetInvoke(parameterInfos, "GetValue", index)
    parameterType = dotnetGet(parameterInfo, "ParameterType")
    isByRef = dotnetGet(parameterType, "IsByRef")
    isPointer = dotnetGet(parameterType, "IsPointer")
    isByRefLike = dotnetGet(parameterType, "IsByRefLike")
    if isByRef.toBool or isPointer.toBool or isByRefLike.toBool:
      dotnetError("callable bridge does not support byref, pointer, or byref-like parameters", E_INVALIDARG)

  registration = DotnetDelegateRegistration(host: host, callback: callback, parameterCount: parameterCount)
  context = cast[pointer](registration)
  acquire(DotnetDelegateLock)
  DotnetDelegateRegistrations[context] = registration
  release(DotnetDelegateLock)
  registrationAdded = true

  try:
    expressionType = getManagedType(host, "System.Linq.Expressions.Expression, System.Linq.Expressions")
    objectType = getManagedType(host, "System.Object, System.Private.CoreLib")
    marshalClass = loadClass(host, "System.Runtime.InteropServices.Marshal", "System.Private.CoreLib")

    ensureDelegateBridge(host)
    bridgeType = getManagedType(host, "WinimDotnetDelegateBridge.Bridge, " & DotnetDelegateBridgeAssemblyName)
    nativeDelegateType = getManagedType(host, "WinimDotnetDelegateBridge.Callback, " & DotnetDelegateBridgeAssemblyName)

    callbackPointer = newObject(host, "System.IntPtr", cast[int64](cast[DotnetDelegateEntryPoint](dotnetDelegateEntryPoint)))
    nativeDelegate = dotnetInvoke(marshalClass, "GetDelegateForFunctionPointer", callbackPointer, nativeDelegateType)

    contextValue = newObject(host, "System.IntPtr", cast[int64](context))
    returnTypeName = dotnetGet(returnType, "FullName")
    invokeName = if $returnTypeName == "System.Void": "InvokeVoid" else: "Invoke"

    bodyBuilder = proc(expression: DotnetClass, parameters: seq[DotnetObject]): DotnetObject =
      var
        boxedParameters: seq[DotnetObject]
        boxedParameterArray, argumentsExpression, nativeDelegateExpression,
          contextExpression, callArguments, bridgeCall: DotnetObject
      defer:
        release(bridgeCall, callArguments, contextExpression,
          nativeDelegateExpression, argumentsExpression, boxedParameterArray)
        boxedParameters.release()

      for parameter in parameters:
        boxedParameters.add dotnetInvoke(expression, "Convert", parameter, objectType)

      boxedParameterArray = newManagedArray(host, expressionType, boxedParameters)
      argumentsExpression = dotnetInvoke(expression, "NewArrayInit", objectType, boxedParameterArray)
      nativeDelegateExpression = dotnetInvoke(expression, "Constant", nativeDelegate)
      contextExpression = dotnetInvoke(expression, "Constant", contextValue)
      callArguments = newManagedArray(host, expressionType, [nativeDelegateExpression, contextExpression, argumentsExpression])
      bridgeCall = dotnetInvoke(expression, "Call", bridgeType, invokeName, nil, callArguments)

      if invokeName == "InvokeVoid":
        result = bridgeCall
        bridgeCall = nil
      else:
        result = dotnetInvoke(expression, "Convert", bridgeCall, returnType)

    result = newDelegate(host, delegateType, bodyBuilder)
    registrationAdded = false
  except Exception:
    raise

proc getManagedType*(assemblyQualifiedName: string): DotnetObject =
  ## Returns a managed `System.Type` through the current thread's host.
  getManagedType(requireCurrentHost(), assemblyQualifiedName)

proc newManagedArray*(elementType: DotnetObject, values: openArray[DotnetObject]): DotnetObject =
  ## Creates a managed array through the current thread's host.
  newManagedArray(requireCurrentHost(), elementType, values)

proc newDelegate*(delegateType: DotnetObject, parameters: openArray[DotnetObject], body: DotnetObject): DotnetObject =
  ## Compiles a managed expression body into any compatible delegate type.
  ##
  ## `delegateType` must be a managed `System.Type` representing a delegate,
  ## `parameters` must contain the corresponding managed parameter
  ## expressions, and `body` is the expression returned by the delegate.
  ## This is a low-level managed expression API; it does not automatically
  ## marshal an arbitrary Nim proc or closure into a .NET delegate.
  newDelegate(requireCurrentHost(), delegateType, parameters, body)

proc newDelegate*(delegateType: DotnetObject, bodyBuilder: DotnetDelegateBodyBuilder): DotnetObject =
  ## Creates a managed delegate by building its body from the delegate
  ## signature. The builder receives the expression type proxy and the
  ## parameter expressions created for `Invoke`.
  newDelegate(requireCurrentHost(), delegateType, bodyBuilder)

proc newDelegate*(delegateType: DotnetObject, callback: DotnetDelegateCallback): DotnetObject =
  ## Creates a managed delegate backed by a Nim callback bridge.
  ##
  ## Delegate parameters are boxed as managed objects and passed to the
  ## callback as temporary `DotnetObject` wrappers. The callback result is
  ## unboxed or cast to the delegate's declared return type. Byref, pointer,
  ## and byref-like parameters and return types are not supported. The
  ## callback must run on the host's owning thread.
  newDelegate(requireCurrentHost(), delegateType, callback)

converter dotnetObjectToBool*(self: DotnetObject): bool =
  ## Converts a managed Boolean value to Nim `bool` in Boolean contexts.
  ## This is the implicit form of `toBool`; nil or non-Boolean managed values
  ## retain the same conversion errors as the explicit procedure.
  self.toBool

converter dotnetObjectToString*(self: DotnetObject): string =
  ## Converts a `DotnetObject` to its managed `ToString()` representation.
  $self

proc canFallbackToIndexable(sourceError: ref DotnetError): bool {.inline.} =
  ## Only a resolver-level missing member permits the Count/Length fallback.
  ## A managed method that throws MissingMethod/ MissingMember is reported as
  ## TargetInvocationException and must keep its original failure.
  sourceError.code == dotnetMissingMethodHResult or
    sourceError.code == dotnetMissingMemberHResult

iterator pairs*(source: DotnetObject): tuple[index: int, value: DotnetObject] =
  ## Iterates a managed collection as `(index, value)` pairs.
  ##
  ## Supports an `IEnumerator`, an `IEnumerable`/`GetEnumerator` pattern, and
  ## finally an indexable object with `Count` or `Length` and an indexer.
  var
    sourceType, enumeratorInterface, enumerator, moved, countValue, lengthValue: DotnetObject
    hasEnumerator = true
    disposeEnumeratorOnExit = false
  defer:
    if disposeEnumeratorOnExit:
      bridgeOperation(requireObject(enumerator), disposeObject, enumerator.handle, "", "")
      if enumerator != source: release(enumerator)
    release(lengthValue, countValue, moved, enumeratorInterface, sourceType)

  sourceType = dotnetInvoke(source, "GetType")
  enumeratorInterface = dotnetInvoke(sourceType, "GetInterface", "System.Collections.IEnumerator")

  if not enumeratorInterface.isNil:
    enumerator = source
  else:
    try: enumerator = dotnetInvoke(source, "GetEnumerator")
    except DotnetError as error:
      if not canFallbackToIndexable(error): raise
      hasEnumerator = false

  if hasEnumerator:
    disposeEnumeratorOnExit = true
    var index = 0
    while true:
      var hasNext = false
      moved = dotnetInvoke(enumerator, "MoveNext")
      hasNext = moved.toBool
      if not hasNext: break

      let value = dotnetInvoke(enumerator, "Current")
      yield (index, value)
      inc index
  else:
    var count: int
    try:
      countValue = dotnetGet(source, "Count")
      count = countValue.toInt

    except DotnetError as error:
      if not canFallbackToIndexable(error): raise
      lengthValue = dotnetGet(source, "Length")
      count = lengthValue.toInt

    for index in 0 ..< count:
      let value = dotnetInvoke(source, "get_Item", index)
      yield (index, value)

iterator items*(source: DotnetObject): DotnetObject =
  ## Iterates the values of a managed collection.
  for _, item in pairs(source):
    yield item

proc reformatDotnetAssignment(n: NimNode): NimNode =
  expectKind(n, nnkAsgn)
  let
    call = n[0]
    member = call[0]
    receiver = member[0].copyNimTree
    memberName = "set_" & member.last.toStrLit.strVal

  result = newCall(bindSym("dotnetInvoke"), receiver, newStrLitNode(memberName))
  for i in 1 ..< call.len:
    result.add(call[i].copyNimTree)
  result.add(n[1].copyNimTree)

proc reformatDotnetScript(n: NimNode): NimNode =
  result = n
  if n.kind == nnkAsgn and n[0].kind == nnkCall and n[0][0].kind == nnkDotExpr:
    result = reformatDotnetAssignment(n)
  elif n.len != 0:
    for i in 0 ..< n.len:
      n[i] = reformatDotnetScript(n[i])

macro `.`*(v: DotnetObject, name: untyped, vargs: varargs[untyped]): untyped =
  ## Shorthand for instance methods, properties, and fields. Member names are
  ## resolved at runtime; explicit helpers remain available for dynamic names.
  result = newCall(bindSym("dotnetInvoke"), v, newStrLitNode($name))
  for item in vargs:
    result.add item

macro `.=`*(v: DotnetObject, name: untyped, vargs: varargs[untyped]): untyped =
  ## Shorthand for setting an instance property or field.
  result = newCall(bindSym("dotnetSet"), v, newStrLitNode($name))
  for item in vargs:
    result.add item

macro `.`*(v: DotnetClass, name: untyped, vargs: varargs[untyped]): untyped =
  ## Shorthand for static methods, properties, fields, and constructors on a
  ## type proxy.
  let memberName = $name
  let normalizedName = memberName.toLowerAscii
  if normalizedName == "run" and vargs.len == 1:
    result = newCall(bindSym("runStaticApplication"), v, vargs[0])
    return
  result = newCall(bindSym("dotnetInvoke"), v, newStrLitNode($name))
  for item in vargs:
    result.add item

macro `.=`*(v: DotnetClass, name: untyped, vargs: varargs[untyped]): untyped =
  ## Shorthand for setting a static property or field.
  result = newCall(bindSym("dotnetSet"), v, newStrLitNode($name))
  for item in vargs:
    result.add item

macro dotnetScript*(x: untyped): untyped =
  ## Extends property assignment to indexed setters such as
  ## `a.b(c, d) = e`, which invokes the managed `set_b` method.
  reformatDotnetScript(x)
